/**
 * Story data for the shared cards (ui/), read from the same fixtures the tests and
 * MCP View contracts use (shared/fixtures/, regenerated by the backend). Stories then
 * show real engine output, and stay current when the fixtures are regenerated.
 */

import type {
  ResultCardData,
  ResultDetails,
  ScenarioCompareData,
  ScenarioSummaryData,
} from "@lucerna/ui";
import fixture from "../../../shared/fixtures/view-data.json";
import previous from "../../../shared/fixtures/view-data-previous.json";

const analyze = fixture.analyze_roth_conversions;

export const resultCard = analyze.structured_content as unknown as ResultCardData;
export const resultDetails = analyze.view_meta as unknown as ResultDetails;
export const previousResultCard = previous.analyze_roth_conversions
  .structured_content as unknown as ResultCardData;
export const previousResultDetails = previous.analyze_roth_conversions
  .view_meta as unknown as ResultDetails;

export const bracketFill = resultDetails.bracket_fill!;

export const compare = fixture.compare_roth_scenarios
  .structured_content as unknown as ScenarioCompareData;
export const recordedScenario = fixture.prepare_scenario
  .structured_content as unknown as ScenarioSummaryData;
